CREATE TABLE `benefit` (
  `BenefitNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `PlanNum` bigint(20) NOT NULL,
  `PatPlanNum` bigint(20) NOT NULL,
  `CovCatNum` bigint(20) NOT NULL,
