  `TimePeriod` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `QuantityQualifier` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `Quantity` tinyint(3) unsigned NOT NULL DEFAULT 0,
