  PRIMARY KEY (`BenefitNum`),
  KEY `indexPlanNum` (`PlanNum`),
  KEY `indexPatPlanNum` (`PatPlanNum`),
  KEY `CovCatNum` (`CovCatNum`),
  KEY `BenefitType` (`BenefitType`),
  KEY `Percent` (`Percent`),
  KEY `MonetaryAmt` (`MonetaryAmt`),
  KEY `TimePeriod` (`TimePeriod`),
  KEY `QuantityQualifier` (`QuantityQualifier`),
  KEY `Quantity` (`Quantity`),
  KEY `CodeNum` (`CodeNum`),
  KEY `CoverageLevel` (`CoverageLevel`),
  KEY `SecDateTEntry` (`SecDateTEntry`),
  KEY `SecDateTEdit` (`SecDateTEdit`),
  KEY `CodeGroupNum` (`CodeGroupNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

